public class TestAverage {
    public static void main(String[] args) {
        double score1 = 85.5;
        double score2 = 92.3;
        double score3 = 77.8;
        double average = (score1 + score2 + score3) / 3;
        int percentage = (int)average;
        System.out.println("Average: " + percentage + "%");
    }
}
